import {
  type ReactNode,
  type Ref,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
} from 'react'
import { AccessibilityInfo } from 'react-native'
import {
  type GetProps,
  type SizeTokens,
  type TamaguiElement,
  View,
  XStack,
  isWeb,
  styled,
} from 'tamagui/unstyled'
import { Badge } from '../badge/Badge'
import { Portal } from '../portal/Portal'
import { ScrollArea } from '../scroll-area/ScrollArea'
import { Text } from '../typography/Text'
import { VisuallyHidden } from '../visually-hidden/VisuallyHidden'
import { shadows } from '@advui/theme'
import { useControllableState } from '../../hooks/useControllableState'
import { useRipple } from '../../hooks/useRipple'
import { type KanbanColumn, type KanbanItem, type KanbanMove, findItem, moveItem } from './moves'
import type { DragTarget } from './place'
import { useDrag } from './useDrag'

export interface KanbanLabels {
  /** Read with each card on web: how to move it with the keyboard. */
  instructions: string
  /** Names a column's list: its title and card count. */
  column: (title: string, count: number) => string
  /** Shown in a column with no cards. */
  empty: string
  pickedUp: (item: string, column: string, position: number, count: number) => string
  moved: (item: string, column: string, position: number, count: number) => string
  dropped: (item: string, column: string, position: number, count: number) => string
  cancelled: (item: string) => string
  /** Screen reader actions on iOS and Android. */
  moveUp: string
  moveDown: string
  moveTo: (column: string) => string
}

const defaultLabels: KanbanLabels = {
  instructions:
    'Press Space to pick the card up. Then the arrow keys move it, Space drops it and Escape puts it back.',
  column: (title, count) => `${title}, ${count === 1 ? '1 card' : `${count} cards`}`,
  empty: 'No cards',
  pickedUp: (item, column, position, count) =>
    `Picked up ${item}. ${column}, position ${position} of ${count}.`,
  moved: (item, column, position, count) => `${item}: ${column}, position ${position} of ${count}.`,
  dropped: (item, column, position, count) =>
    `Dropped ${item} in ${column}, position ${position} of ${count}.`,
  cancelled: (item) => `${item} is back where it was.`,
  moveUp: 'Move up',
  moveDown: 'Move down',
  moveTo: (column) => `Move to ${column}`,
}

const KanbanFrame = styled(View, {
  displayName: 'Kanban',
})

const ColumnFrame = styled(View, {
  displayName: 'KanbanColumn',
  flexShrink: 0,
  gap: '2',
  padding: '2',
  borderRadius: 'lg',
  backgroundColor: 'muted',
})

export const KanbanCardFrame = styled(View, {
  displayName: 'KanbanCard',
  gap: '1',
  padding: '3',
  borderRadius: 'lg',
  borderWidth: 1,
  borderColor: 'border',
  backgroundColor: 'card',
  outlineColor: 'focus-visible:ring',
  outlineStyle: 'focus-visible:solid',
  outlineWidth: 'focus-visible:2px',
  outlineOffset: 'focus-visible:2px',
  variants: {
    state: {
      rest: {},
      // Picked up with the keyboard: it moves with the arrow keys.
      lifted: { borderColor: 'primary' },
      // Where a dragged card will land: the card itself follows the pointer.
      placeholder: { backgroundColor: 'primarySoft', borderColor: 'primary' },
    },
    movable: {
      true: { cursor: 'grab' },
    },
  } as const,
  defaultVariants: { state: 'rest' },
})

type Drag = {
  itemId: string
  columnId: string
  index: number
  from: { columnId: string; index: number }
  mode: 'keyboard' | 'pointer'
}

export interface KanbanProps<T extends KanbanItem = KanbanItem> extends Omit<
  GetProps<typeof KanbanFrame>,
  'children' | 'defaultValue' | 'columnWidth'
> {
  /** The columns and their cards (controlled). */
  value?: KanbanColumn<T>[]
  defaultValue?: KanbanColumn<T>[]
  /** Called with the columns after a card moves. */
  onValueChange?: (columns: KanbanColumn<T>[]) => void
  /** Called after a card moves, with where from and where to. */
  onItemMove?: (move: KanbanMove) => void
  /** Makes cards open on a press (or Enter). */
  onItemPress?: (item: T) => void
  /** Draws a card's content. Default: its title and description. */
  renderItem?: (item: T) => ReactNode
  /** Width of each column. Default `72`. */
  columnWidth?: SizeTokens | number
  /** Names the board. Recommended. */
  'aria-label'?: string
  labels?: Partial<KanbanLabels>
  ref?: Ref<TamaguiElement>
}

/**
 * Cards in columns that people move by dragging, with the keyboard, or with
 * screen reader actions on iOS and Android, such as tasks through stages.
 */
export function Kanban<T extends KanbanItem = KanbanItem>({
  value,
  defaultValue = [],
  onValueChange,
  onItemMove,
  onItemPress,
  renderItem,
  columnWidth = '72',
  'aria-label': label,
  labels: labelsProp,
  ref,
  ...props
}: KanbanProps<T>) {
  const labels = { ...defaultLabels, ...labelsProp }
  const [columns, setColumns] = useControllableState({
    value,
    defaultValue,
    onChange: onValueChange,
  })
  const [drag, setDrag] = useState<Drag | null>(null)
  const dragRef = useRef(drag)
  dragRef.current = drag
  // The board as the drag would leave it: the card sits at its new place.
  const preview = drag ? moveItem(columns, drag.itemId, drag.columnId, drag.index) : columns
  const previewRef = useRef<readonly KanbanColumn<T>[]>(preview)
  previewRef.current = preview
  const draggingId = useRef<string | null>(null)
  draggingId.current = drag?.itemId ?? null

  const boardRef = useRef<TamaguiElement>(null)
  const columnNodes = useRef(new Map<string, TamaguiElement>())
  const cardNodes = useRef(new Map<string, TamaguiElement>())
  const instructionsId = useId()
  // An id for each card's description; item ids may hold spaces, which a
  // list of ids cannot.
  const descriptionIds = useRef(new Map<string, string>())
  const descriptionId = (itemId: string) => {
    let id = descriptionIds.current.get(itemId)
    if (!id)
      descriptionIds.current.set(itemId, (id = `${instructionsId}-${descriptionIds.current.size}`))
    return id
  }
  const [message, setMessage] = useState({ text: '', key: 0 })
  const announce = (text: string) => {
    if (isWeb) setMessage((current) => ({ text, key: current.key + 1 }))
    else AccessibilityInfo.announceForAccessibility(text)
  }

  // A card that moved to another column mounts again there: give it focus
  // back. After a pointer drag without scrolling: the card is in view.
  const focusAfter = useRef<{ id: string; scroll: boolean } | null>(null)
  const focusTimer = useRef<ReturnType<typeof setTimeout>>(undefined)
  useLayoutEffect(() => {
    if (!focusAfter.current) return
    const { id, scroll } = focusAfter.current
    focusAfter.current = null
    if (isWeb) {
      ;(cardNodes.current.get(id) as HTMLElement | undefined)?.focus({ preventScroll: !scroll })
      return
    }
    // Native: once the old view has left the screen, or TalkBack loses focus again.
    clearTimeout(focusTimer.current)
    focusTimer.current = setTimeout(() => {
      const node = cardNodes.current.get(id) as { isConnected?: boolean } | undefined
      if (node?.isConnected !== false)
        AccessibilityInfo.sendAccessibilityEvent(node as never, 'focus')
    }, 250)
  })
  useEffect(() => () => clearTimeout(focusTimer.current), [])

  const place = (target: { columnId: string; index: number }, list = previewRef.current) => {
    const column = list.find((c) => c.id === target.columnId)!
    return [column.title, target.index + 1, column.items.length] as const
  }

  const start = (itemId: string, mode: Drag['mode']) => {
    const found = findItem(columns, itemId)
    if (!found || found.item.disabled) return
    const from = { columnId: found.column.id, index: found.index }
    const next = { itemId, mode, ...from, from }
    // Now, not on the next render: the move that started a drag is placed too.
    dragRef.current = next
    draggingId.current = itemId
    setDrag(next)
    if (mode === 'keyboard') announce(labels.pickedUp(found.item.title, ...place(from, columns)))
  }

  const over = (target: DragTarget, spoken: boolean) => {
    const current = dragRef.current
    if (!current || (current.columnId === target.columnId && current.index === target.index)) return
    const next = { ...current, ...target }
    dragRef.current = next
    setDrag(next)
    // A pointer drag refocuses the card once, when it drops.
    if (current.mode === 'keyboard' && current.columnId !== target.columnId) {
      focusAfter.current = { id: current.itemId, scroll: true }
    }
    if (spoken) {
      const item = findItem(columns, current.itemId)!.item
      announce(
        labels.moved(
          item.title,
          ...place(target, moveItem(columns, item.id, target.columnId, target.index)),
        ),
      )
    }
  }

  const commit = (itemId: string, from: Drag['from'], to: DragTarget) => {
    const next = moveItem(columns, itemId, to.columnId, to.index)
    if (from.columnId !== to.columnId || from.index !== to.index) {
      setColumns(next)
      onItemMove?.({ itemId, from, to })
    }
    return next
  }

  const drop = () => {
    const current = dragRef.current
    if (!current) return
    dragRef.current = null
    setDrag(null)
    const to = { columnId: current.columnId, index: current.index }
    const next = commit(current.itemId, current.from, to)
    const item = findItem(next, current.itemId)!.item
    announce(labels.dropped(item.title, ...place(to, next)))
    focusAfter.current = { id: current.itemId, scroll: current.mode === 'keyboard' }
  }

  const cancel = () => {
    const current = dragRef.current
    if (!current) return
    dragRef.current = null
    setDrag(null)
    announce(labels.cancelled(findItem(columns, current.itemId)!.item.title))
    if (current.columnId !== current.from.columnId) {
      focusAfter.current = { id: current.itemId, scroll: current.mode === 'keyboard' }
    }
  }

  const pointer = useDrag({
    preview: previewRef,
    draggingId,
    board: boardRef,
    columns: columnNodes,
    cards: cardNodes,
    canDrag: (itemId) => !dragRef.current && !findItem(columns, itemId)?.item.disabled,
    onStart: (itemId) => start(itemId, 'pointer'),
    onOver: (target) => over(target, false),
    onDrop: drop,
    onCancel: cancel,
  })

  type CardKey = { key: string; preventDefault: () => void }
  const onCardKeyDown = (item: T, event: CardKey) => {
    const current = dragRef.current
    if (current?.mode === 'keyboard' && current.itemId === item.id) {
      const columnIndex = columns.findIndex((column) => column.id === current.columnId)
      const count = previewRef.current[columnIndex]!.items.length
      switch (event.key) {
        case 'ArrowUp':
        case 'ArrowDown': {
          event.preventDefault()
          const index = current.index + (event.key === 'ArrowUp' ? -1 : 1)
          if (index >= 0 && index < count) over({ columnId: current.columnId, index }, true)
          return
        }
        case 'ArrowLeft':
        case 'ArrowRight': {
          event.preventDefault()
          const column = columns[columnIndex + (event.key === 'ArrowLeft' ? -1 : 1)]
          if (!column) return
          const others = column.items.filter((other) => other.id !== item.id).length
          over({ columnId: column.id, index: Math.min(current.index, others) }, true)
          return
        }
        case ' ':
        case 'Enter':
          event.preventDefault()
          return drop()
        case 'Escape':
          event.preventDefault()
          return cancel()
      }
      return
    }
    if (current) return
    if (event.key === 'Enter' && onItemPress) {
      event.preventDefault()
      onItemPress(item)
    } else if (event.key === ' ' || event.key === 'Enter') {
      event.preventDefault()
      start(item.id, 'keyboard')
    }
  }

  // Native screen readers: each card's actions move it one step.
  const moveBy = (item: T, action: string) => {
    const found = findItem(columns, item.id)
    if (!found) return
    const columnIndex = columns.indexOf(found.column)
    const from = { columnId: found.column.id, index: found.index }
    let to: DragTarget | null = null
    if (action === 'moveUp') to = { ...from, index: from.index - 1 }
    if (action === 'moveDown') to = { ...from, index: from.index + 1 }
    if (action === 'moveLeft' || action === 'moveRight') {
      const column = columns[columnIndex + (action === 'moveLeft' ? -1 : 1)]
      if (column) to = { columnId: column.id, index: Math.min(from.index, column.items.length) }
    }
    if (!to || to.index < 0) return
    const next = commit(item.id, from, to)
    announce(labels.moved(item.title, ...place(to, next)))
    focusAfter.current = { id: item.id, scroll: true }
  }

  const setRefs = (node: TamaguiElement | null) => {
    if (typeof ref === 'function') ref(node)
    else if (ref) ref.current = node
  }

  const draggedItem = drag ? findItem(columns, drag.itemId)?.item : undefined

  return (
    <KanbanFrame ref={setRefs} {...props}>
      <ScrollArea
        ref={boardRef}
        orientation="horizontal"
        aria-label={label}
        // Native: the board stays put while a card is dragged.
        {...(!isWeb && drag && { scrollEnabled: false })}
      >
        <XStack
          gap="3"
          alignItems="flex-start"
          {...(isWeb && drag?.mode === 'pointer' && { userSelect: 'none', cursor: 'grabbing' })}
          {...pointer.boardProps}
        >
          {preview.map((column, columnIndex) => (
            <ColumnFrame key={column.id} width={columnWidth}>
              <XStack
                alignItems="center"
                justifyContent="space-between"
                gap="2"
                minHeight="7"
                paddingHorizontal="1"
              >
                <Text size="sm" weight="semibold" numberOfLines={1} flexShrink={1}>
                  {column.title}
                </Text>
                {/* The list's name has the count. */}
                <Badge size="sm" variant="secondary" aria-hidden>
                  {column.items.length}
                </Badge>
              </XStack>
              <View
                ref={(node: TamaguiElement | null) => {
                  if (node) columnNodes.current.set(column.id, node)
                  else columnNodes.current.delete(column.id)
                }}
                // A list needs items: an empty column is a named group.
                role={(isWeb ? (column.items.length ? 'list' : 'group') : undefined) as never}
                {...(isWeb && {
                  'aria-label': labels.column(column.title, column.items.length),
                })}
                gap="2"
                minHeight="16"
                {...pointer.columnProps(column.id)}
              >
                {column.items.map((item, index) => {
                  const state =
                    drag?.itemId !== item.id
                      ? 'rest'
                      : drag.mode === 'keyboard'
                        ? 'lifted'
                        : 'placeholder'
                  return (
                    <View
                      key={item.id}
                      role={(isWeb ? 'listitem' : undefined) as never}
                      {...pointer.cardLayout(item.id, column.id)}
                    >
                      <KanbanCard
                        item={item}
                        state={state}
                        cardRef={(node) => {
                          if (node) cardNodes.current.set(item.id, node)
                          else if (cardNodes.current.get(item.id) === node) {
                            cardNodes.current.delete(item.id)
                          }
                        }}
                        // The default card is named by its title and
                        // described by its description; a custom one is
                        // named by its content.
                        name={renderItem ? undefined : item.title}
                        describedBy={
                          [
                            !renderItem && item.description && descriptionId(item.id),
                            !item.disabled && instructionsId,
                          ]
                            .filter(Boolean)
                            .join(' ') || undefined
                        }
                        onPress={
                          onItemPress
                            ? () => {
                                if (!pointer.consumePress() && !dragRef.current) onItemPress(item)
                              }
                            : undefined
                        }
                        onKeyDown={(event) => onCardKeyDown(item, event)}
                        onBlur={() => {
                          // Focus left a card picked up with the keyboard:
                          // put it back. A card that moved to another column
                          // has focus again by now.
                          setTimeout(() => {
                            const current = dragRef.current
                            if (current?.mode !== 'keyboard' || current.itemId !== item.id) return
                            if (document.activeElement !== cardNodes.current.get(item.id)) cancel()
                          })
                        }}
                        actions={
                          item.disabled
                            ? undefined
                            : [
                                ...(index > 0 ? [{ name: 'moveUp', label: labels.moveUp }] : []),
                                ...(index < column.items.length - 1
                                  ? [{ name: 'moveDown', label: labels.moveDown }]
                                  : []),
                                ...(columns[columnIndex - 1]
                                  ? [
                                      {
                                        name: 'moveLeft',
                                        label: labels.moveTo(columns[columnIndex - 1]!.title),
                                      },
                                    ]
                                  : []),
                                ...(columns[columnIndex + 1]
                                  ? [
                                      {
                                        name: 'moveRight',
                                        label: labels.moveTo(columns[columnIndex + 1]!.title),
                                      },
                                    ]
                                  : []),
                              ]
                        }
                        onAction={(action) => moveBy(item, action)}
                        dragProps={item.disabled ? {} : pointer.cardProps(item.id)}
                      >
                        {renderItem ? (
                          renderItem(item)
                        ) : (
                          <DefaultContent item={item} descriptionId={descriptionId(item.id)} />
                        )}
                      </KanbanCard>
                    </View>
                  )
                })}
                {column.items.length === 0 ? (
                  <View alignItems="center" justifyContent="center" padding="4">
                    <Text size="xs" tone="muted">
                      {labels.empty}
                    </Text>
                  </View>
                ) : null}
              </View>
            </ColumnFrame>
          ))}
        </XStack>
      </ScrollArea>
      {isWeb ? (
        <>
          <VisuallyHidden id={instructionsId}>{labels.instructions}</VisuallyHidden>
          <VisuallyHidden role="status" aria-live="assertive">
            {message.text ? <Text key={message.key}>{message.text}</Text> : null}
          </VisuallyHidden>
        </>
      ) : null}
      {pointer.overlay && draggedItem ? (
        <Portal zIndex="popover">
          <View
            position="absolute"
            left={pointer.overlay.x - pointer.overlay.dx}
            top={pointer.overlay.y - pointer.overlay.dy}
            width={pointer.overlay.width}
            pointerEvents="none"
            aria-hidden
          >
            <KanbanCardFrame {...shadows.md} {...(isWeb && { cursor: 'grabbing' })}>
              {renderItem ? renderItem(draggedItem) : <DefaultContent item={draggedItem} />}
            </KanbanCardFrame>
          </View>
        </Portal>
      ) : null}
    </KanbanFrame>
  )
}

function DefaultContent({ item, descriptionId }: { item: KanbanItem; descriptionId?: string }) {
  return (
    <>
      <Text size="sm" weight="medium">
        {item.title}
      </Text>
      {item.description ? (
        <Text id={descriptionId} size="xs" tone="muted" numberOfLines={3}>
          {item.description}
        </Text>
      ) : null}
    </>
  )
}

type AccessibilityAction = { name: string; label: string }

function KanbanCard({
  item,
  state,
  cardRef,
  name,
  describedBy,
  onPress,
  onKeyDown,
  onBlur,
  actions,
  onAction,
  dragProps,
  children,
}: {
  item: KanbanItem
  state: 'rest' | 'lifted' | 'placeholder'
  cardRef: (node: TamaguiElement | null) => void
  name: string | undefined
  describedBy: string | undefined
  onPress: (() => void) | undefined
  onKeyDown: (event: { key: string; preventDefault: () => void }) => void
  onBlur: () => void
  actions: AccessibilityAction[] | undefined
  onAction: (action: string) => void
  dragProps: Record<string, unknown>
  children: ReactNode
}) {
  const movable = !item.disabled
  // The drag's own onPressOut runs too.
  const ripple = useRipple({
    color: 'foreground',
    radius: 'lg',
    disabled: !onPress,
    onPressOut: dragProps.onPressOut as never,
  })
  return (
    <KanbanCardFrame
      ref={cardRef}
      state={state}
      movable={movable}
      role="button"
      {...(name && {
        // iOS and Android have no descriptions: the description joins the name.
        'aria-label': !isWeb && item.description ? `${name}, ${item.description}` : name,
      })}
      {...(isWeb
        ? {
            tabIndex: 0,
            'aria-describedby': describedBy,
            // So a drag never selects text, nor opens a long-press menu.
            userSelect: 'none',
            onKeyDown,
            onBlur,
          }
        : {
            accessible: true,
            ...(actions?.length && {
              accessibilityActions: actions,
              onAccessibilityAction: (event: { nativeEvent: { actionName: string } }) =>
                onAction(event.nativeEvent.actionName),
            }),
          })}
      {...(state === 'lifted' && shadows.md)}
      {...(onPress && { onPress })}
      {...(ripple.active && { backgroundColor: 'press:card' })}
      {...dragProps}
      {...ripple.props}
    >
      {ripple.element}
      {/* The placeholder keeps the card's size, with nothing in it. */}
      <View gap="1" {...(state === 'placeholder' && { opacity: 0 })}>
        {children}
      </View>
    </KanbanCardFrame>
  )
}

export interface KanbanItem {
  id: string
  /** The card's name: shown by default, and read by screen readers. */
  title: string
  /** Shown under the title by default. */
  description?: string
  /** Stays where it is: cannot be picked up. */
  disabled?: boolean
}

export interface KanbanColumn<T extends KanbanItem = KanbanItem> {
  id: string
  title: string
  items: T[]
}

export interface KanbanPlace {
  columnId: string
  /** Position in the column, from 0. */
  index: number
}

export interface KanbanMove {
  itemId: string
  from: KanbanPlace
  /** Where it is now: the index counts the column without the card in its old place. */
  to: KanbanPlace
}

/** Where an item is: its column and index. */
export function findItem<T extends KanbanItem>(
  columns: readonly KanbanColumn<T>[],
  itemId: string,
) {
  for (const column of columns) {
    const index = column.items.findIndex((item) => item.id === itemId)
    if (index !== -1) return { column, index, item: column.items[index]! }
  }
  return null
}

/**
 * The columns with one item moved to `index` in another (or the same)
 * column. Columns the move does not touch keep their identity.
 */
export function moveItem<T extends KanbanItem>(
  columns: readonly KanbanColumn<T>[],
  itemId: string,
  toColumnId: string,
  toIndex: number,
): KanbanColumn<T>[] {
  const found = findItem(columns, itemId)
  if (!found || !columns.some((column) => column.id === toColumnId)) return [...columns]
  return columns.map((column) => {
    let items = column.items
    if (column.id === found.column.id) items = items.filter((item) => item.id !== itemId)
    if (column.id === toColumnId) {
      const index = Math.max(0, Math.min(toIndex, items.length))
      items = [...items.slice(0, index), found.item, ...items.slice(index)]
    }
    return items === column.items ? column : { ...column, items }
  })
}

import type { RefObject } from 'react'
import type { TamaguiElement } from 'tamagui/unstyled'
import type { KanbanColumn } from './moves'

export interface DragTarget {
  columnId: string
  index: number
}

/** Where the floating card is: the pointer, less where the card was held. */
export interface DragOverlay {
  x: number
  y: number
  dx: number
  dy: number
  width: number
}

export interface DragOptions {
  /** The columns as the drag would leave them, to find the place under the pointer. */
  preview: RefObject<readonly KanbanColumn[]>
  draggingId: RefObject<string | null>
  /** The board's scrolling box, scrolled when the pointer nears its edges. */
  board: RefObject<TamaguiElement | null>
  /** Each column's list of cards, and each card. */
  columns: RefObject<Map<string, TamaguiElement>>
  cards: RefObject<Map<string, TamaguiElement>>
  canDrag: (itemId: string) => boolean
  onStart: (itemId: string) => void
  onOver: (target: DragTarget) => void
  onDrop: () => void
  onCancel: () => void
}

export type Rect = { x: number; y: number; width: number; height: number }

/** The place under a point: the nearest column, and the index among its other cards. */
export function placeAt(
  x: number,
  y: number,
  preview: readonly KanbanColumn[],
  draggingId: string | null,
  rectOf: (kind: 'column' | 'card', id: string) => Rect | null,
): DragTarget | null {
  let best: KanbanColumn | null = null
  let distance = Infinity
  for (const column of preview) {
    const rect = rectOf('column', column.id)
    if (!rect) continue
    const away = x < rect.x ? rect.x - x : x > rect.x + rect.width ? x - rect.x - rect.width : 0
    if (away < distance) {
      best = column
      distance = away
    }
  }
  if (!best) return null
  let index = 0
  for (const item of best.items) {
    if (item.id === draggingId) continue
    const rect = rectOf('card', item.id)
    if (rect && y > rect.y + rect.height / 2) index++
  }
  return { columnId: best.id, index }
}

import { useEffect, useRef, useState } from 'react'
import { type DragOptions, type DragOverlay, placeAt } from './place'

// A mouse drag starts after this many pixels; a touch drag after holding
// still this long, so a swipe still scrolls the board.
const slop = 4
const holdMs = 250
// Near the board's edges a drag scrolls it sideways.
const edge = 48
const scrollStep = 16

type Press = {
  itemId: string
  pointerId: number
  touch: boolean
  x: number
  y: number
  overlay: DragOverlay
  started: boolean
  timer?: ReturnType<typeof setTimeout>
  /** Removes the listeners added for this press: its own, from that render. */
  detach: () => void
}

type PointerDown = {
  button: number
  pointerId: number
  pointerType: string
  clientX: number
  clientY: number
  currentTarget: HTMLElement
  preventDefault: () => void
}

/**
 * Web: pointer events on the card, then on the window, so the drag goes on
 * while the card moves between columns (it mounts again there). A mouse
 * starts dragging once it moves; a finger once it has held still.
 */
export function useDrag(options: DragOptions) {
  const handlers = useRef(options)
  handlers.current = options
  const press = useRef<Press | null>(null)
  const [overlay, setOverlay] = useState<DragOverlay | null>(null)
  // A click follows the pointerup that ends a drag; it is not a press.
  const dragged = useRef(false)

  const rectOf = (kind: 'column' | 'card', id: string) => {
    const node = (
      kind === 'column' ? handlers.current.columns : handlers.current.cards
    ).current.get(id)
    const rect = (node as HTMLElement | undefined)?.getBoundingClientRect()
    return rect ? { x: rect.left, y: rect.top, width: rect.width, height: rect.height } : null
  }

  const end = () => {
    const current = press.current
    if (!current) return
    clearTimeout(current.timer)
    current.detach()
    press.current = null
    setOverlay(null)
  }

  const begin = () => {
    const current = press.current
    if (!current || current.started) return
    current.started = true
    handlers.current.onStart(current.itemId)
    setOverlay(current.overlay)
  }

  function onMove(event: PointerEvent) {
    const current = press.current
    if (!current || event.pointerId !== current.pointerId) return
    if (!current.started) {
      const moved = Math.hypot(event.clientX - current.x, event.clientY - current.y) > slop
      // A finger that moves before the hold is scrolling.
      if (current.touch) return moved ? end() : undefined
      if (!moved) return
      begin()
    }
    const next = { ...current.overlay, x: event.clientX, y: event.clientY }
    current.overlay = next
    setOverlay(next)
    const board = handlers.current.board.current as HTMLElement | null
    if (board) {
      const rect = board.getBoundingClientRect()
      if (event.clientX < rect.left + edge) board.scrollLeft -= scrollStep
      else if (event.clientX > rect.right - edge) board.scrollLeft += scrollStep
    }
    const target = placeAt(
      event.clientX,
      event.clientY,
      handlers.current.preview.current,
      handlers.current.draggingId.current,
      rectOf,
    )
    if (target) handlers.current.onOver(target)
  }

  function onUp(event: PointerEvent) {
    const current = press.current
    if (!current || event.pointerId !== current.pointerId) return
    if (current.started) {
      dragged.current = true
      setTimeout(() => {
        dragged.current = false
      })
      handlers.current.onDrop()
    }
    end()
  }

  function onPointerCancel(event: PointerEvent) {
    const current = press.current
    if (!current || event.pointerId !== current.pointerId) return
    if (current.started) handlers.current.onCancel()
    end()
  }

  function onKey(event: KeyboardEvent) {
    if (event.key !== 'Escape' || !press.current?.started) return
    event.preventDefault()
    event.stopPropagation()
    handlers.current.onCancel()
    end()
  }

  // Once a touch drag has started, the page must not scroll under it.
  function blockScroll(event: TouchEvent) {
    if (press.current?.started) event.preventDefault()
  }

  // Unmounted mid-drag: no listeners stay behind.
  useEffect(
    () => () => {
      clearTimeout(press.current?.timer)
      press.current?.detach()
    },
    [],
  )

  return {
    overlay,
    boardProps: {},
    columnProps: (_columnId: string) => ({}),
    consumePress: () => dragged.current,
    cardProps: (itemId: string) => ({
      // A long touch would open the browser's menu over the card.
      onContextMenu: (event: { preventDefault: () => void }) => {
        if (press.current?.touch) event.preventDefault()
      },
      onPointerDown: (event: PointerDown) => {
        if (event.button !== 0 || press.current || !handlers.current.canDrag(itemId)) return
        const touch = event.pointerType === 'touch'
        const card = event.currentTarget
        const rect = card.getBoundingClientRect()
        if (!touch) {
          // No text selection while dragging. That also skips the focus a
          // press would give, so the card takes it here.
          event.preventDefault()
          card.focus({ preventScroll: true })
        }
        press.current = {
          itemId,
          pointerId: event.pointerId,
          touch,
          x: event.clientX,
          y: event.clientY,
          overlay: {
            x: event.clientX,
            y: event.clientY,
            dx: event.clientX - rect.left,
            dy: event.clientY - rect.top,
            width: rect.width,
          },
          started: false,
          ...(touch && { timer: setTimeout(begin, holdMs) }),
          detach: () => {
            window.removeEventListener('pointermove', onMove)
            window.removeEventListener('pointerup', onUp)
            window.removeEventListener('pointercancel', onPointerCancel)
            window.removeEventListener('keydown', onKey, true)
            document.removeEventListener('touchmove', blockScroll)
          },
        }
        window.addEventListener('pointermove', onMove)
        window.addEventListener('pointerup', onUp)
        window.addEventListener('pointercancel', onPointerCancel)
        window.addEventListener('keydown', onKey, true)
        if (touch) document.addEventListener('touchmove', blockScroll, { passive: false })
      },
    }),
    cardLayout: (_itemId: string, _columnId: string) => ({}),
  }
}

import { useEffect, useMemo, useRef, useState } from 'react'
import { type GestureResponderEvent, type LayoutChangeEvent, PanResponder } from 'react-native'
import { type DragOptions, type DragOverlay, type Rect, placeAt } from './place'

type Measurable = { measureInWindow?: (callback: (...rect: number[]) => void) => void }

/**
 * Native: a long press picks the card up. From then on the board claims each
 * move before the card or a scroll view can (as Color Picker's guard does),
 * until the finger lifts. Columns are measured in the window when the drag
 * starts; cards report their place in their column as they lay out.
 */
export function useDrag(options: DragOptions) {
  const handlers = useRef(options)
  handlers.current = options
  const [overlay, setOverlay] = useState<DragOverlay | null>(null)
  const active = useRef<{ itemId: string; overlay: DragOverlay } | null>(null)
  const claimed = useRef(false)
  const columnRects = useRef(new Map<string, Rect>())
  const cardLayouts = useRef(new Map<string, Rect>())
  // The card that lists each card: its place is relative to that column.
  const cardColumns = useRef(new Map<string, string>())

  const rectOf = (kind: 'column' | 'card', id: string): Rect | null => {
    if (kind === 'column') return columnRects.current.get(id) ?? null
    const layout = cardLayouts.current.get(id)
    const column = columnRects.current.get(cardColumns.current.get(id) ?? '')
    return layout && column ? { ...layout, x: column.x + layout.x, y: column.y + layout.y } : null
  }

  const finish = (drop: boolean) => {
    if (!active.current) return
    active.current = null
    claimed.current = false
    setOverlay(null)
    if (drop) handlers.current.onDrop()
    else handlers.current.onCancel()
  }

  const pan = useMemo(
    () =>
      PanResponder.create({
        onMoveShouldSetPanResponderCapture: () => !!active.current,
        onPanResponderGrant: () => {
          claimed.current = true
        },
        onPanResponderMove: (_, gesture) => {
          const current = active.current
          if (!current) return
          current.overlay = { ...current.overlay, x: gesture.moveX, y: gesture.moveY }
          setOverlay(current.overlay)
          const target = placeAt(
            gesture.moveX,
            gesture.moveY,
            handlers.current.preview.current,
            handlers.current.draggingId.current,
            rectOf,
          )
          if (target) handlers.current.onOver(target)
        },
        onPanResponderTerminationRequest: () => false,
        onPanResponderRelease: () => finish(true),
        onPanResponderTerminate: () => finish(false),
      }),
    [],
  )

  useEffect(
    () => () => {
      active.current = null
    },
    [],
  )

  return {
    overlay,
    boardProps: pan.panHandlers,
    columnProps: (columnId: string) => ({
      onLayout: () => {
        const node = handlers.current.columns.current.get(columnId) as Measurable | undefined
        node?.measureInWindow?.((x, y, width, height) =>
          columnRects.current.set(columnId, { x: x!, y: y!, width: width!, height: height! }),
        )
      },
    }),
    consumePress: () => false,
    cardLayout: (itemId: string, columnId: string) => ({
      onLayout: (event: LayoutChangeEvent) => {
        cardLayouts.current.set(itemId, event.nativeEvent.layout)
        cardColumns.current.set(itemId, columnId)
      },
    }),
    cardProps: (itemId: string) => ({
      delayLongPress: 300,
      onLongPress: (event: GestureResponderEvent) => {
        if (active.current || !handlers.current.canDrag(itemId)) return
        const { pageX, pageY, locationX, locationY } = event.nativeEvent
        // Columns move as the board scrolls: measure them now.
        for (const [columnId, node] of handlers.current.columns.current) {
          ;(node as Measurable).measureInWindow?.((x, y, width, height) =>
            columnRects.current.set(columnId, { x: x!, y: y!, width: width!, height: height! }),
          )
        }
        const width = cardLayouts.current.get(itemId)?.width ?? 0
        const next = { x: pageX, y: pageY, dx: locationX, dy: locationY, width }
        active.current = { itemId, overlay: next }
        handlers.current.onStart(itemId)
        setOverlay(next)
      },
      // A long press that lifts without moving: the board never took the
      // gesture, so the card hears the end. The board, once it has taken
      // the gesture, ends the drag itself.
      onPressOut: () => {
        setTimeout(() => {
          if (active.current && !claimed.current) finish(true)
        })
      },
    }),
  }
}

